import { useContext } from "react";
import { ComplaintContext } from "../context/ComplaintContext";
import { useNavigate } from "react-router-dom";
import "../styles/global.css";

function Dashboard() {
  const { complaints } = useContext(ComplaintContext);
  const navigate = useNavigate();

  const departments = [
    {
      name: "Public Works",
      icon: "🏗️",
      sub: ["Road damage","Street light","Garbage","Bridge issue","Footpath"],
    },
    {
      name: "Water & Sanitation",
      icon: "💧",
      sub: ["Water leakage","Drainage","Sewage","Low pressure","Water supply"],
    },
    {
      name: "Health & Safety",
      icon: "🏥",
      sub: ["Hospital issue","Mosquito","Emergency","Food safety","Ambulance"],
    },
    {
      name: "Electricity",
      icon: "⚡",
      sub: ["Power cut","Transformer","Billing","Loose wire"],
    },
    {
      name: "Transport",
      icon: "🚌",
      sub: ["Bus delay","Traffic signal","Accident","Parking"],
    },
  ];

  const getCount = (dept) =>
    complaints.filter((c) => c.department === dept).length;

  return (
    <>
      {/* ⭐ HEADER */}
      <div className="citizen-header">
        <div>
          <h2>Citizen's Voice</h2>
          <p>Select department to file complaint</p>
        </div>

        <div
          className="status-bar"
          onClick={() => navigate("/track")}
        >
          📋 View Application Status
        </div>
      </div>

      {/* ⭐ GRID */}
      <div className="dept-grid">
        {departments.map((d) => (
          <div
            key={d.name}
            className="dept-card"
            onClick={() =>
              navigate("/add", {
                state: { department: d.name, categories: d.sub },
              })
            }
          >
            <div className="badge">{getCount(d.name)}</div>
            <div className="icon">{d.icon}</div>
            <h3>{d.name}</h3>
            <p>Click to file complaint</p>
          </div>
        ))}
      </div>
    </>
  );
}

export default Dashboard;
